import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    s = data[0]
    t = data[1]

    n = len(s)
    m = len(t)
    MOD = 10**9 + 7

    if m > n:
        print(0)
        return

    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k > 0 and t[k] != t[i]:
            k = pi[k-1]
        if t[k] == t[i]:
            k += 1
        pi[i] = k

    j = 0
    match_end = [-1] * n
    for i in range(n):
        while j > 0 and s[i] != t[j]:
            j = pi[j-1]
        if s[i] == t[j]:
            j += 1
        if j == m:
            match_end[i] = i
            j = pi[j-1]

    first_valid_start = [0] * n
    current_first = -1
    for i in range(n):
        if match_end[i] != -1:
            current_first = i - m + 1
        if current_first != -1:
            first_valid_start[i] = current_first
        else:
            first_valid_start[i] = -1

    dp = [0] * (n + 1)
    sum_dp = [0] * (n + 1)

    for i in range(n):
        idx = i + 1
        prev_sum = sum_dp[i] if i > 0 else 0

        if first_valid_start[i] != -1:
            start_idx = first_valid_start[i]
            if start_idx == 0:
                count = 1
            else:
                count = dp[start_idx] + 1

            term = (count * (i - start_idx + 1)) % MOD
            total = (prev_sum + term) % MOD
        else:
            total = prev_sum

        dp[idx] = total
        sum_dp[idx] = (sum_dp[i] + total) % MOD

    print(sum_dp[n])

solve()
